// POST { e_sorder_id: "S2737687.0001" }. Quotes hang off the generation's
// HubSpot deal, so the gen suffix is required.
const b = $input.first().json.body || {};
const m = String(b.e_sorder_id || '').trim().toUpperCase().match(/^S?(\d+)\.(\d{1,4})$/);
if (!m) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing or invalid e_sorder_id (expected S1234567.0001).', step: 'validate' } } }];
return [{ json: { ok: true, e_sorder_id: 'S' + m[1] + '.' + m[2].padStart(4, '0') } }];

// Needs a deal with line items (the Eclipse sync puts them on the deal; the
// quote gets copies). Its quote ids go to the existing-quote check.
const v = $('Validate').first().json;
const d = $input.first().json || {};
const stop = (statusCode, body) => [{ json: { ok: false, statusCode, body } }];
if (d.error) return stop(502, { success: false, error: 'HubSpot deal lookup failed: ' + d.error + ' ' + JSON.stringify(d.message || '').substring(0, 300), step: 'getDeal' });
if (d.objectFound === false || !d.id) return stop(404, { success: false, error: 'No HubSpot deal for ' + v.e_sorder_id + ' yet.', step: 'getDeal' });
const ids = (key) => [...new Set((((d.associations || {})[key] || {}).results || []).map((r) => String(r.id)).filter(Boolean))];
const lineIds = ids('line items');
if (!lineIds.length) return stop(409, { success: false, error: 'The HubSpot deal for ' + v.e_sorder_id + ' has no line items yet.', step: 'getDeal' });
const p = d.properties || {};
return [{ json: { ok: true, dealId: String(d.id), ownerId: p.hubspot_owner_id || '', priceExpires: p.e_price_expire_date || '', lineIds: lineIds.join(','), quoteIds: ids('quotes').join(',') } }];

// A quote with a public link already on the deal: return it, make nothing
// (a double click or two reps at once must not make two quotes).
const day = (x) => {
  if (x == null || x === '') return null;
  const d = /^\d+$/.test(String(x)) ? new Date(Number(x)) : new Date(String(x));
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};
const today = new Date().toISOString().slice(0, 10);
const toQuote = (r) => {
  const p = r.properties || {};
  const expires = day(p.hs_expiration_date);
  const link = p.hs_quote_link || (p.hs_proposal_domain && p.hs_proposal_slug ? 'https://' + p.hs_proposal_domain + '/' + p.hs_proposal_slug : null);
  return {
    id: String(r.id), title: p.hs_title || '', number: p.hs_quote_number || '', status: p.hs_status || '', link,
    amount: p.hs_quote_amount != null && p.hs_quote_amount !== '' ? Number(p.hs_quote_amount) : null,
    created: p.hs_createdate || null, expires, expired: !!expires && expires < today,
  };
};
const c = $('Check deal').first().json;
const v = $('Validate').first().json;
const rows = c.quoteIds ? $input.all().flatMap((i) => Array.isArray(i.json.results) ? i.json.results : []) : [];
const quotes = rows.filter((r) => !r.archived).map(toQuote).sort((a, b) => String(b.created || '').localeCompare(String(a.created || '')));
const q = quotes.find((x) => x.link);
if (q) return [{ json: { ok: false, statusCode: 200, body: { success: true, created: false, e_sorder_id: v.e_sorder_id, hs_deal_id: c.dealId, quote: q, quotes } } }];
return [{ json: { ok: true } }];

// Copies of the deal's line items for the quote (a quote needs its own),
// in Eclipse line order, skipping lines with no quantity. Same fields as
// Fairbank's existing quotes; the template reads name, description,
// quantity, e_uom, price, amount and the product id.
const r = $input.first().json || {};
if (r.error) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot line item read failed: ' + r.error, step: 'dealLines' } } }];
const COPY = ['name', 'description', 'hs_sku', 'quantity', 'price', 'hs_cost_of_goods_sold', 'hs_product_id', 'e_uom', 'e_uom_qty', 'e_product_id_'];
const num = (x) => (x == null || x === '' || isNaN(Number(x)) ? Infinity : Number(x));
const rows = (Array.isArray(r.results) ? r.results : [])
  .filter((l) => !l.archived && Number((l.properties || {}).quantity) > 0)
  .sort((a, b) => num(a.properties.e_sorder_line_number) - num(b.properties.e_sorder_line_number));
if (!rows.length) return [{ json: { ok: false, statusCode: 409, body: { success: false, error: 'The HubSpot deal has no line items with a quantity.', step: 'dealLines' } } }];
const inputs = rows.map((l, i) => {
  const props = { hs_position_on_quote: String(i) };
  for (const k of COPY) { const val = l.properties[k]; if (val != null && val !== '') props[k] = val; }
  return { properties: props };
});
return [{ json: { ok: true, body: { inputs } } }];

// The quote: Fairbank's quote template (558349092401), linked to the deal
// (its header comes from deal properties) and to the new line items.
// Association type ids: quote→template 286, quote→deal 64, quote→line item 67.
const TEMPLATE_ID = '558349092401';
const v = $('Validate').first().json;
const c = $('Check deal').first().json;
const r = $input.first().json || {};
if (r.error) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot line item create failed: ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 300), step: 'createLines' } } }];
const lineIds = (Array.isArray(r.results) ? r.results : []).map((x) => String(x.id));
if (!lineIds.length) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot created no line items.', step: 'createLines' } } }];
// Expiry: the deal's price expiry (Eclipse), or 10 days out when that is
// missing or already past ("Price is firm for 10 days" on the template).
const today = new Date().toISOString().slice(0, 10);
const plus10 = new Date(Date.now() + 10 * 864e5).toISOString().slice(0, 10);
const pe = String(c.priceExpires || '').slice(0, 10);
const expires = /^\d{4}-\d{2}-\d{2}$/.test(pe) && pe >= today ? pe : plus10;
const assoc = (id, typeId) => ({ to: { id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: typeId }] });
const properties = {
  hs_title: 'Quote ' + v.e_sorder_id,
  hs_status: 'APPROVAL_NOT_NEEDED',
  hs_expiration_date: expires,
  hs_currency: 'USD',
  hs_language: 'en',
  hs_locale: 'en-us',
};
if (c.ownerId) properties.hubspot_owner_id = c.ownerId;
return [{ json: { ok: true, body: { inputs: [{ properties, associations: [assoc(TEMPLATE_ID, 286), assoc(c.dealId, 64), ...lineIds.map((id) => assoc(id, 67))] }] } } }];

// The new quote, same shape as the quote lookup flow. Its public link is
// hs_quote_link, else https://<hs_proposal_domain>/<hs_proposal_slug>.
const day = (x) => {
  if (x == null || x === '') return null;
  const d = /^\d+$/.test(String(x)) ? new Date(Number(x)) : new Date(String(x));
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};
const today = new Date().toISOString().slice(0, 10);
const toQuote = (r) => {
  const p = r.properties || {};
  const expires = day(p.hs_expiration_date);
  const link = p.hs_quote_link || (p.hs_proposal_domain && p.hs_proposal_slug ? 'https://' + p.hs_proposal_domain + '/' + p.hs_proposal_slug : null);
  return {
    id: String(r.id), title: p.hs_title || '', number: p.hs_quote_number || '', status: p.hs_status || '', link,
    amount: p.hs_quote_amount != null && p.hs_quote_amount !== '' ? Number(p.hs_quote_amount) : null,
    created: p.hs_createdate || null, expires, expired: !!expires && expires < today,
  };
};
const v = $('Validate').first().json;
const c = $('Check deal').first().json;
const r = $input.first().json || {};
if (r.error) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot quote create failed: ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 300), step: 'createQuote' } } }];
const row = (Array.isArray(r.results) ? r.results : [])[0];
if (!row) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot returned no quote.', step: 'createQuote' } } }];
const quote = toQuote(row);
return [{ json: { ok: true, statusCode: 200, body: { success: true, created: true, e_sorder_id: v.e_sorder_id, hs_deal_id: c.dealId, quote, quotes: [quote] } } }];

// A new quote's public page answers 404 for a few seconds while HubSpot
// publishes it. Check it every second, up to 20 tries, and answer only once
// it is up, so View Quote never opens on HubSpot's 404 page. Still 404 after
// that: answer with page_ready false (the page asks to try again shortly).
// Errors from earlier steps (ok false) pass straight through.
const j = $input.first().json;
const link = j.ok && j.body && j.body.quote && j.body.quote.link;
if (!link) return [{ json: j }];
const t0 = Date.now();
let status = null, tries = 0;
for (; tries < 20; tries++) {
  if (tries) await new Promise((res) => setTimeout(res, 1000));
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: link, returnFullResponse: true, ignoreHttpStatusErrors: true, json: false });
    status = r.statusCode;
  } catch (e) {
    status = 'error: ' + e.message;
  }
  if (status !== 404 && typeof status === 'number') break;
}
const ready = typeof status === 'number' && status !== 404;
return [{ json: Object.assign({}, j, { body: Object.assign({}, j.body, { page_ready: ready, page_status: status, page_wait_ms: Date.now() - t0, page_tries: Math.min(tries + 1, 20) }) }) }];
